'use client';

import React, { useState } from 'react';
import { usePOS } from '@/modules/pos/context/POSContext';
import { useRouter } from 'next/navigation';
import {
    Search,
    ShoppingCart,
    ChevronRight,
    Plus,
    Minus,
    Trash2,
    Clock,
    ArrowRight,
    Search as SearchIcon,
    Scan,
    Info,
    Star,
    Leaf,
    Flame
} from 'lucide-react';
import { mockPOSProducts, mockPOSCategories } from '../mock/posData';
import { POSProduct, POSCartItem } from '../types/pos';
import { formatCurrency } from '@/utils';

export const POSMenuScreen: React.FC = () => {
    const { session, setCustomer } = usePOS();
    const router = useRouter();
    const [activeCategory, setActiveCategory] = useState<string>(mockPOSCategories[0].id);
    const [searchQuery, setSearchQuery] = useState('');
    const [cart, setCart] = useState<POSCartItem[]>([]);
    const [selectedProduct, setSelectedProduct] = useState<POSProduct | null>(null);

    // Filter products
    const filteredProducts = mockPOSProducts.filter(p =>
        (p.categoryId === activeCategory || activeCategory === 'all') &&
        (p.name.toLowerCase().includes(searchQuery.toLowerCase()) || p.sku.toLowerCase().includes(searchQuery.toLowerCase()))
    );

    const addToCart = (product: POSProduct) => {
        const existing = cart.find(item => item.productId === product.id);
        if (existing) {
            setCart(cart.map(item =>
                item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item
            ));
        } else {
            setCart([...cart, {
                id: Math.random().toString(36).substr(2, 9),
                productId: product.id,
                name: product.name,
                price: product.price,
                quantity: 1,
                modifiers: []
            }]);
        }
    };

    const updateQuantity = (id: string, delta: number) => {
        setCart(cart.map(item => {
            if (item.id === id) {
                const newQty = Math.max(1, item.quantity + delta);
                return { ...item, quantity: newQty };
            }
            return item;
        }));
    };

    const removeFromCart = (id: string) => {
        setCart(cart.filter(item => item.id !== id));
    };

    const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const tax = subtotal * 0.1;
    const total = subtotal + tax;

    return (
        <div className="flex h-screen bg-white text-brand font-sans overflow-hidden">
            {/* LEFT: CATEGORIES PANEL (Section 7) */}
            <aside className="w-24 md:w-32 bg-brand/5 border-r border-brand/10 flex flex-col items-center py-6 gap-2 flex-shrink-0 overflow-y-auto custom-scrollbar">
                <button
                    onClick={() => setActiveCategory('all')}
                    className={`w-16 h-16 md:w-20 md:h-20 rounded-2xl flex flex-col items-center justify-center gap-1 transition-all ${activeCategory === 'all' ? 'bg-brand text-white shadow-lg shadow-brand/20' : 'text-brand/40 hover:bg-brand/10 hover:text-brand'}`}
                >
                    <div className="text-[10px] font-black uppercase tracking-widest">All</div>
                </button>
                {mockPOSCategories.map(cat => (
                    <button
                        key={cat.id}
                        onClick={() => setActiveCategory(cat.id)}
                        className={`w-16 h-16 md:w-20 md:h-20 rounded-2xl flex flex-col items-center justify-center gap-1 transition-all p-2 text-center ${activeCategory === cat.id ? 'bg-brand text-white shadow-lg shadow-brand/20' : 'text-brand/40 hover:bg-brand/10 hover:text-brand'}`}
                    >
                        <span className="text-[10px] font-black uppercase tracking-tight leading-tight">{cat.name}</span>
                    </button>
                ))}
            </aside>

            {/* CENTER: PRODUCTS GRID (Section 7) */}
            <main className="flex-1 flex flex-col min-w-0 bg-white">
                {/* Search & Tool Bar */}
                <header className="h-20 bg-white border-b border-brand/10 px-8 flex items-center justify-between gap-6">
                    <div className="flex-1 relative">
                        <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-brand/20" size={20} />
                        <input
                            type="text"
                            placeholder="Search name, SKU, or barcode (Ctrl+F)"
                            className="w-full h-12 bg-brand/5 border border-brand/10 rounded-xl pl-12 pr-6 text-brand font-bold focus:border-brand/40 focus:ring-4 focus:ring-brand/5 outline-none transition-all placeholder:text-brand/20"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                    </div>
                    <div className="flex items-center gap-2">
                        <button className="h-12 w-12 bg-brand/5 rounded-xl flex items-center justify-center text-brand/40 hover:text-brand hover:bg-brand/10 transition-all border border-brand/10">
                            <Scan size={20} />
                        </button>
                        <button className="h-12 w-12 bg-brand/5 rounded-xl flex items-center justify-center text-brand/40 hover:text-brand hover:bg-brand/10 transition-all border border-brand/10">
                            <Star size={20} />
                        </button>
                    </div>
                </header>

                {/* Product Grid */}
                <div className="flex-1 overflow-y-auto p-8 grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-6 custom-scrollbar">
                    {filteredProducts.map(product => (
                        <button
                            key={product.id}
                            onClick={() => product.hasVariants ? setSelectedProduct(product) : addToCart(product)}
                            className="bg-white border-2 border-brand/10 rounded-[2rem] p-4 flex flex-col group transition-all hover:border-brand hover:shadow-xl hover:shadow-brand/5 active:scale-95 text-left relative overflow-hidden h-fit"
                        >
                            <div className="aspect-square bg-brand/5 rounded-2xl mb-4 overflow-hidden relative">
                                <img src={product.image} alt={product.name} className="w-full h-full object-cover transition-transform group-hover:scale-110" />
                                {product.isVeg ? (
                                    <div className="absolute top-2 right-2 w-6 h-6 bg-white rounded-lg flex items-center justify-center shadow-md">
                                        <Leaf size={14} className="text-brand" fill="currentColor" />
                                    </div>
                                ) : (
                                    <div className="absolute top-2 right-2 w-6 h-6 bg-white rounded-lg flex items-center justify-center shadow-md">
                                        <Flame size={14} className="text-rose-500" fill="currentColor" />
                                    </div>
                                )}
                            </div>
                            <div className="flex-1">
                                <h4 className="text-sm font-black text-brand leading-tight mb-1 line-clamp-2">{product.name}</h4>
                                <div className="text-[10px] font-bold text-brand/40 uppercase tracking-widest mb-2">{product.sku}</div>
                            </div>
                            <div className="flex items-center justify-between mt-2 pt-2 border-t border-brand/5">
                                <span className="text-sm font-black text-brand">${product.price.toFixed(2)}</span>
                                <div className="p-2 bg-brand/5 rounded-lg text-brand group-hover:bg-brand group-hover:text-white transition-all">
                                    <Plus size={16} />
                                </div>
                            </div>
                            {!product.isAvailable && (
                                <div className="absolute inset-0 bg-white/80 backdrop-blur-[2px] flex items-center justify-center z-10">
                                    <div className="bg-rose-500 text-white px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest">
                                        Out of stock
                                    </div>
                                </div>
                            )}
                        </button>
                    ))}
                </div>
            </main>

            {/* RIGHT: CART & SUMMARY (Section 9) */}
            <aside className="w-80 md:w-96 bg-white border-l border-brand/10 flex flex-col flex-shrink-0">
                <header className="p-8 border-b border-brand/10 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <ShoppingCart size={24} className="text-brand" />
                        <div>
                            <h3 className="text-xl font-black text-brand tracking-tight">Active Order</h3>
                            <div className="flex items-center gap-2">
                                <span className="text-[10px] font-bold text-brand/40 uppercase tracking-widest">{session?.channel || 'Dine-In'}</span>
                                <span className="w-1 h-1 rounded-full bg-brand/30"></span>
                                <span className="text-[10px] font-bold text-brand/40 uppercase tracking-widest">{cart.length} Items</span>
                            </div>
                        </div>
                    </div>
                </header>

                {/* Cart Items */}
                <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
                    {cart.map(item => (
                        <div key={item.id} className="bg-brand/5 border border-brand/10 rounded-2xl p-4 group animate-in slide-in-from-right duration-300">
                            <div className="flex justify-between items-start mb-3">
                                <div className="flex-1 min-w-0">
                                    <h5 className="text-sm font-black text-brand truncate">{item.name}</h5>
                                    <p className="text-[10px] font-bold text-brand/40 uppercase">Unit: ${item.price.toFixed(2)}</p>
                                </div>
                                <button
                                    onClick={() => removeFromCart(item.id)}
                                    className="p-1 text-brand/20 hover:text-rose-500 transition-all opacity-0 group-hover:opacity-100"
                                >
                                    <Trash2 size={16} />
                                </button>
                            </div>
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-1 bg-white border border-brand/10 rounded-xl p-1 shadow-sm">
                                    <button
                                        onClick={() => updateQuantity(item.id, -1)}
                                        className="w-8 h-8 rounded-lg flex items-center justify-center text-brand/40 hover:bg-brand/5 hover:text-brand transition-all"
                                    >
                                        <Minus size={14} />
                                    </button>
                                    <span className="w-8 text-center text-xs font-black">{item.quantity}</span>
                                    <button
                                        onClick={() => updateQuantity(item.id, 1)}
                                        className="w-8 h-8 rounded-lg flex items-center justify-center text-brand/40 hover:bg-brand/5 hover:text-brand transition-all"
                                    >
                                        <Plus size={14} />
                                    </button>
                                </div>
                                <span className="text-sm font-black text-brand">${(item.price * item.quantity).toFixed(2)}</span>
                            </div>
                        </div>
                    ))}
                    {cart.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center py-20 text-center opacity-30">
                            <ShoppingCart size={48} className="mb-4" />
                            <p className="text-xs font-black uppercase tracking-widest">Cart is Empty</p>
                        </div>
                    )}
                </div>

                {/* Pricing Summary (Section 10) */}
                <div className="p-8 border-t border-brand/10 bg-brand/5 space-y-4">
                    <div className="space-y-2">
                        <div className="flex justify-between text-xs font-bold text-brand/60 uppercase tracking-widest">
                            <span>Subtotal</span>
                            <span>${subtotal.toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between text-xs font-bold text-brand/60 uppercase tracking-widest">
                            <span>Service Tax (10%)</span>
                            <span>${tax.toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between text-lg font-black text-brand pt-2 border-t border-brand/10">
                            <span className="tracking-tighter uppercase">Total Amount</span>
                            <span className="tracking-tighter">${total.toFixed(2)}</span>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-3">
                        <button className="py-4 bg-white border-2 border-brand/10 rounded-2xl text-[10px] font-black uppercase tracking-widest text-brand/40 hover:text-brand hover:border-brand transition-all">
                            Hold
                        </button>
                        <button
                            onClick={() => setCart([])}
                            className="py-4 bg-white border-2 border-brand/10 rounded-2xl text-[10px] font-black uppercase tracking-widest text-brand/40 hover:text-rose-500 hover:border-rose-500 transition-all"
                        >
                            Clear
                        </button>
                    </div>
                    <button
                        onClick={() => router.push('/pos/payment')}
                        className="w-full py-5 bg-brand text-white rounded-2xl text-sm font-black uppercase tracking-widest shadow-xl shadow-brand/20 hover:bg-brand-dark active:scale-[0.98] transition-all flex items-center justify-center gap-2"
                    >
                        Proceed to Payment
                        <ArrowRight size={18} />
                    </button>
                </div>
            </aside>

            {/* PRODUCT CUSTOMIZATION MODAL (Section 8) placeholder */}
            {selectedProduct && (
                <div className="fixed inset-0 bg-brand/20 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
                    <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl overflow-hidden border-4 border-brand/10 flex flex-col max-h-[90vh]">
                        <div className="p-8 border-b border-brand/10 flex items-center justify-between">
                            <div className="flex items-center gap-4">
                                <div className="w-16 h-16 bg-brand/5 rounded-2xl overflow-hidden">
                                    <img src={selectedProduct.image} className="w-full h-full object-cover" />
                                </div>
                                <div>
                                    <h3 className="text-2xl font-black text-brand tracking-tight">{selectedProduct.name}</h3>
                                    <p className="text-brand/40 text-xs font-bold uppercase tracking-widest">Customizing Item</p>
                                </div>
                            </div>
                            <button onClick={() => setSelectedProduct(null)} className="w-12 h-12 bg-brand/5 rounded-full flex items-center justify-center text-brand/40 hover:text-brand transition-all">
                                <Plus className="rotate-45" size={24} />
                            </button>
                        </div>

                        <div className="flex-1 overflow-y-auto p-8 space-y-10 custom-scrollbar">
                            {/* Variants (Section 8) */}
                            <div>
                                <h4 className="text-xs font-black text-brand uppercase tracking-[0.2em] mb-4">Select Size</h4>
                                <div className="grid grid-cols-3 gap-4">
                                    {['Small', 'Medium', 'Large'].map(size => (
                                        <button key={size} className="p-4 rounded-2xl border-2 border-brand/10 text-brand font-black hover:border-brand hover:bg-brand/5 transition-all text-sm">
                                            {size}
                                            <div className="text-[10px] font-medium opacity-40">+$0.00</div>
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Modifiers (Section 8) */}
                            <div>
                                <h4 className="text-xs font-black text-brand uppercase tracking-[0.2em] mb-4">Extra Toppings</h4>
                                <div className="grid grid-cols-2 gap-4">
                                    {['Extra Cheese', 'Olives', 'Mushrooms', 'Jalapenos'].map(topping => (
                                        <div key={topping} className="p-4 bg-brand/5 rounded-2xl flex items-center justify-between border border-brand/10">
                                            <span className="text-sm font-bold text-brand">{topping}</span>
                                            <div className="flex items-center gap-3">
                                                <span className="text-[10px] font-black text-brand/40">+$1.50</span>
                                                <div className="w-6 h-6 rounded-lg border-2 border-brand/20 flex items-center justify-center transition-all bg-white hover:border-brand cursor-pointer">
                                                    <Plus size={14} className="text-brand/40" />
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>

                        <div className="p-8 bg-brand/5 border-t border-brand/10 flex items-center justify-between">
                            <div className="flex flex-col">
                                <span className="text-[10px] font-black text-brand/40 uppercase tracking-widest">Item Total</span>
                                <span className="text-2xl font-black text-brand">${selectedProduct.price.toFixed(2)}</span>
                            </div>
                            <button
                                onClick={() => { addToCart(selectedProduct); setSelectedProduct(null); }}
                                className="px-12 py-5 bg-brand text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-brand/20 hover:bg-brand-dark transition-all"
                            >
                                Add item
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};
